#!/usr/bin/env bash
# aws-controllers-k8s/ec2-chart 1.18.4 - base variant: default
# Path: fetch this entry's retained objects, check their SHA-256, then apply
# them with kubectl. It uses curl, shasum, awk and kubectl. It needs no cub
# CLI and no ConfigHub account.
# Generated by scripts/generate-public-site.mjs from this entry's listing:
# https://confighub.github.io/helm-expt/site/listings/aws-controllers-k8s-ec2-chart-1-18-4-default.json
# Entry page: https://confighub.github.io/helm-expt/site/charts/aws-controllers-k8s-ec2-chart-1-18-4.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

for tool in curl awk kubectl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf '%s is required and was not found.\n' "$tool" >&2
    exit 1
  fi
done
if command -v shasum >/dev/null 2>&1; then
  sha256_of() { shasum -a 256 "$1" | awk '{print $1}'; }
elif command -v sha256sum >/dev/null 2>&1; then
  sha256_of() { sha256sum "$1" | awk '{print $1}'; }
else
  printf 'shasum is required and was not found.\n' >&2
  exit 1
fi

work=./aws-controllers-k8s-ec2-chart-1-18-4-default-objects
objects_url=https://raw.githubusercontent.com/confighub/helm-expt/main/recipes/aws-controllers-k8s/ec2-chart/1.18.4/revisions/default/r001/rendered/release-objects.yaml
objects_sha256=f554824764fd9d781aaea445b728b209a93a190ccd8865ccdf235139377fcc59

say "Fetch the retained objects into $work/objects.yaml"
mkdir -p "$work"
curl -fsSL -o "$work/objects.yaml" "$objects_url"

say "Check the file against the SHA-256 in the listing"
fetched_sha256="$(sha256_of "$work/objects.yaml")"
if [ "$fetched_sha256" != "$objects_sha256" ]; then
  printf 'The file differs from the listing, so the script stops. Nothing was applied.\n  listing: %s\n  fetched: %s\n' "$objects_sha256" "$fetched_sha256" >&2
  exit 1
fi
printf 'The file matches: sha256 %s\n' "$fetched_sha256"

say "Split the file into its 32 objects. The cluster is untouched so far"
rm -rf "$work/docs" "$work/crds" "$work/rest"
mkdir -p "$work/docs" "$work/crds" "$work/rest"
awk -v dir="$work/docs" 'BEGIN { n = 0; f = sprintf("%s/doc-%04d.yaml", dir, n) } /^---[ \t]*$/ { close(f); n++; f = sprintf("%s/doc-%04d.yaml", dir, n); next } { print > f }' "$work/objects.yaml"
for n in 0002 0004 0006 0008 0010 0012 0014 0016 0018 0020 0022 0024; do mv "$work/docs/doc-$n.yaml" "$work/crds/"; done
for n in 0026 0028 0030 0032 0034 0036 0038 0040 0042 0044; do mv "$work/docs/doc-$n.yaml" "$work/crds/"; done
for n in 0045 0046 0047 0048 0049 0050 0051 0052 0053 0054; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
ls "$work/crds" "$work/rest"

say "Check that kubectl reaches a cluster"
if ! kubectl get --raw /version >/dev/null 2>&1; then
  printf 'kubectl cannot reach a cluster. Point it at a throwaway cluster and re-run this script.\n' >&2
  exit 1
fi
kubectl config current-context 2>/dev/null || true

say "Create the ack-system namespace if it does not exist"
if ! kubectl get namespace ack-system >/dev/null 2>&1; then
  kubectl create namespace ack-system
fi

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Check the 22 CRDs this file holds"
missing_crds=0
if ! kubectl get crd/capacityreservations.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/dhcpoptions.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/egressonlyinternetgateways.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/elasticipaddresses.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/flowlogs.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/instances.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/internetgateways.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/launchtemplates.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/managedprefixlists.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/natgateways.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/networkacls.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/routetables.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/securitygroups.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/subnets.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/transitgateways.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/transitgatewayvpcattachments.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/vpcendpoints.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/vpcendpointserviceconfigurations.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/vpcpeeringconnections.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/vpcs.ec2.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/fieldexports.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/iamroleselectors.services.k8s.aws >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  say "A CRD is missing, so apply the file's CRDs first"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="were applied first"
elif kubectl diff --server-side -f "$work/crds" >/dev/null 2>&1; then
  say "The CRDs already exist and match this file. The script leaves them under their current owner"
  crd_outcome="already existed and matched, so the script left them alone"
elif [ "${APPLY_CRDS:-0}" = "1" ]; then
  say "The existing CRDs differ from this file. APPLY_CRDS=1 is set, so the script applies the file's CRDs"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="differed and were applied, because APPLY_CRDS=1 was set"
else
  say "The CRDs already exist and differ from this file, or another tool owns them"
  cat <<'EOF_CRDS'
This script does not change CRDs it did not just create.
If this is an upgrade, the objects that follow may need the newer CRDs.
To let this script apply the file's CRDs, re-run with:
  APPLY_CRDS=1 bash try-objects.sh
EOF_CRDS
  exit 1
fi
wait_for_crd capacityreservations.ec2.services.k8s.aws
wait_for_crd dhcpoptions.ec2.services.k8s.aws
wait_for_crd egressonlyinternetgateways.ec2.services.k8s.aws
wait_for_crd elasticipaddresses.ec2.services.k8s.aws
wait_for_crd flowlogs.ec2.services.k8s.aws
wait_for_crd instances.ec2.services.k8s.aws
wait_for_crd internetgateways.ec2.services.k8s.aws
wait_for_crd launchtemplates.ec2.services.k8s.aws
wait_for_crd managedprefixlists.ec2.services.k8s.aws
wait_for_crd natgateways.ec2.services.k8s.aws
wait_for_crd networkacls.ec2.services.k8s.aws
wait_for_crd routetables.ec2.services.k8s.aws
wait_for_crd securitygroups.ec2.services.k8s.aws
wait_for_crd subnets.ec2.services.k8s.aws
wait_for_crd transitgateways.ec2.services.k8s.aws
wait_for_crd transitgatewayvpcattachments.ec2.services.k8s.aws
wait_for_crd vpcendpoints.ec2.services.k8s.aws
wait_for_crd vpcendpointserviceconfigurations.ec2.services.k8s.aws
wait_for_crd vpcpeeringconnections.ec2.services.k8s.aws
wait_for_crd vpcs.ec2.services.k8s.aws
wait_for_crd fieldexports.services.k8s.aws
wait_for_crd iamroleselectors.services.k8s.aws

say "Apply the other 10 objects"
kubectl apply -f "$work/rest"

say "Done. The 22 CRDs $crd_outcome. kubectl applied the other 10 objects of this entry's retained file."
say "The script stops here. It did not wait for any workload to start"
